/**
 * Whether links should be openable
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
import '../../../globals.js';
import '../../../chipper/js/browser/initialize-globals.js';
import BooleanProperty from '../../../axon/js/BooleanProperty.js';
import Tandem from '../../../tandem/js/Tandem.js';
import scenery from '../scenery.js';

const allowLinksProperty = new BooleanProperty( !( self?.phet?.chipper?.queryParameters ) || ( self?.phet?.chipper?.queryParameters?.allowLinks ), {
  tandem: Tandem.GENERAL_MODEL.createTandem( 'allowLinksProperty' )
} );

scenery.register( 'allowLinksProperty', allowLinksProperty );

export default allowLinksProperty;